    discount_value numeric(10,2) NOT NULL,
    ends_at timestamp(6) without time zone,
    max_discount_amount numeric(10,2),
    min_order_amount numeric(10,2),
    starts_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone NOT NULL,
    usage_limit integer,
    restaurant_id bigint,
    CONSTRAINT coupons_check CHECK (((discount_value > (0)::numeric) AND (((discount_type)::text <> 'PERCENTAGE'::text) OR (discount_value <= (100)::numeric)) AND ((min_order_amount IS NULL) OR (min_order_amount >= (0)::numeric)) AND ((max_discount_amount IS NULL) OR (max_discount_amount > (0)::numeric)) AND ((usage_limit IS NULL) OR (usage_limit > 0)) AND ((starts_at IS NULL) OR (ends_at IS NULL) OR (ends_at > starts_at)))),
    CONSTRAINT coupons_discount_type_check CHECK (((discount_type)::text = ANY ((ARRAY['PERCENTAGE'::character varying, 'FIXED'::character varying])::text[])))
);

