    customer_id bigint NOT NULL,
    restaurant_id bigint NOT NULL,
    CONSTRAINT orders_check CHECK (((subtotal >= (0)::numeric) AND (delivery_fee >= (0)::numeric) AND (discount >= (0)::numeric) AND (total >= (0)::numeric))),
    CONSTRAINT orders_payment_method_check CHECK (((payment_method)::text = 'CASH_ON_DELIVERY'::text)),
    CONSTRAINT orders_status_check CHECK (((status)::text = ANY ((ARRAY['NEW'::character varying, 'CONFIRMED'::character varying, 'PREPARING'::character varying, 'ON_THE_WAY'::character varying, 'DELIVERED'::character varying, 'CANCELLED'::character varying])::text[])))
);

