    CONSTRAINT restaurants_check CHECK (((estimated_delivery_max_minutes >= estimated_delivery_min_minutes) AND (delivery_fee >= (0)::numeric) AND (minimum_order >= (0)::numeric) AND (rating_average >= (0)::numeric) AND (rating_average <= (5)::numeric) AND (review_count >= 0) AND ((open_time IS NULL) OR (close_time IS NULL) OR (close_time > open_time))))
);

